import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.SUPABASE_URL || process.env.EXPO_PUBLIC_SUPABASE_URL || '';
const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY || '';
const email = 'iperez4242@gmail.com';

if (!supabaseUrl || !serviceRoleKey) {
  console.log('MISSING_CONFIG');
  console.log('supabaseUrl_present:', !!supabaseUrl);
  console.log('serviceRoleKey_present:', !!serviceRoleKey);
  process.exit(1);
}

const admin = createClient(supabaseUrl, serviceRoleKey, {
  auth: { autoRefreshToken: false, persistSession: false },
});

async function audit() {
  try {
    const { data, error } = await admin.auth.admin.listUsers({
      page: 1,
      perPage: 1000,
    });
    if (error) {
      console.log('LIST_USERS_ERROR', error.message, error.code);
      return;
    }
    const user = data.users.find((u) => (u.email || '').toLowerCase() === email);
    if (!user) {
      console.log('USER_NOT_FOUND');
      console.log('total_users:', data.users.length);
      return;
    }
    console.log('USER_FOUND');
    console.log('id:', user.id);
    console.log('email:', user.email);
    console.log('email_confirmed_at:', user.email_confirmed_at || 'null');
    console.log('confirmed_at:', user.confirmed_at || 'null');
    console.log('last_sign_in_at:', user.last_sign_in_at || 'null');
    console.log('created_at:', user.created_at || 'null');
    console.log('updated_at:', user.updated_at || 'null');
    console.log('role:', user.role || 'null');
    console.log('banned:', user.banned || false);
    console.log('providers:', JSON.stringify(user.app_metadata?.providers || user.identities?.map((i) => i.provider) || []));
    console.log('app_metadata:', JSON.stringify(user.app_metadata || {}));
    console.log('user_metadata:', JSON.stringify(user.user_metadata || {}));
    // Check if user has email identity
    const emailIdentity = user.identities?.find((i) => i.provider === 'email');
    console.log('has_email_identity:', !!emailIdentity);
    // Do NOT log password hash or anything sensitive
  } catch (e) {
    console.log('AUDIT_THROW', e instanceof Error ? e.message : String(e));
  }
}

audit();
EOF
